ALTER TABLE batches ADD COLUMN IF NOT EXISTS allow_all_logins BOOLEAN NOT NULL DEFAULT TRUE;
CREATE TABLE mobile_sessions (id TEXT PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, revoked_at TIMESTAMPTZ);
CREATE TABLE batch_login_requests (batch_id VARCHAR(64) REFERENCES batches(id) ON DELETE CASCADE, user_id VARCHAR(36) REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED')), requested_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(batch_id,user_id));
CREATE TABLE batch_account_events (id TEXT PRIMARY KEY, batch_id VARCHAR(64) REFERENCES batches(id) ON DELETE CASCADE, user_id VARCHAR(36) REFERENCES users(id) ON DELETE CASCADE, event TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
